'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var setReadWriteAccessor = require( '@stdlib/utils/define-nonenumerable-read-write-accessor' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isObject = require( '@stdlib/assert/is-plain-object' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isCollection = require( '@stdlib/assert/is-collection' );
var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var format = require( '@stdlib/string/format' );
var unsignedMul = require( '@stdlib/number/uint32/base/mul' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var FLOAT64_MAX_SAFE_INTEGER = require( '@stdlib/constants/float64/max-safe-integer' );
var Uint32Array = require( '@stdlib/array/uint32' );
var gcopy = require( '@stdlib/blas/base/gcopy' );
var typedarray2json = require( '@stdlib/array/to-json' );
var randuint32 = require( './rand_uint32.js' );


// VARIABLES //

// Define the number of state elements for TinyMT32
var N = 4;

// Define a normalization constant when generating double-precision floating-point numbers: 2^53 => 9007199254740992
var FLOAT64_NORMALIZATION_CONSTANT = 1.0 / ( FLOAT64_MAX_SAFE_INTEGER+1.0 ); // eslint-disable-line id-length

// 2^26: 67108864
var TWO_26 = 67108864 >>> 0; // asm type annotation

// Define the maximum normalized pseudorandom double-precision floating-point number: ( (((2^32-1)>>>5)*2^26)+( (2^32-1)>>>6) ) / 2^53
var MAX_NORMALIZED = FLOAT64_MAX_SAFE_INTEGER * FLOAT64_NORMALIZATION_CONSTANT;

// Define the state array schema version:
var STATE_ARRAY_VERSION = 1; // NOTE: anytime the state array schema changes, this value should be incremented!!!

// Define the number of sections in the state array:
var NUM_STATE_SECTIONS = 2; // state, seed

// Define the index offset of the "state" section in the state array:
var STATE_SECTION_OFFSET = 2; // | version | num_sections | state_length | ...state | state_index | seed_length | ...seed |

// Define the index offset of the seed section in the state array:
var SEED_SECTION_OFFSET = N + 4; // | version | num_sections | state_length | ...state | state_index | seed_length | ...seed |

// Define the length of the "fixed" length portion of the state array:
var STATE_FIXED_LENGTH = N + 5; // 1 (version) + 1 (num_sections) + 1 (state_length) + N (state) + 1 (state_index) + 1 (seed_length)

// TinyMT32 constants
var MAT1 = 0x8F7011EE;
var MAT2 = 0xFC78FF1F;
var TMAT = 0x3793FDFF;

// TinyMT32 shift constants
var SH0 = 1;
var SH1 = 10;
var SH8 = 8;
var MASK = 0x7FFFFFFF;

// Initialization constants
var MIN_LOOP = 8;
var PRE_LOOP = 8;
var KNUTH_MULTIPLIER = 1812433253 >>> 0; // asm type annotation


// FUNCTIONS //

/**
* Verifies state array integrity.
*
* @private
* @param {Uint32Array} state - state array
* @param {boolean} FLG - flag indicating whether the state array was provided as an option (true) or an argument (false)
* @returns {(Error|null)} an error or `null`
*/
function verifyState( state, FLG ) {
	var s1;
	if ( FLG ) {
		s1 = 'option';
	} else {
		s1 = 'argument';
	}
	if ( state.length < STATE_FIXED_LENGTH+1 ) {
		return new RangeError( format( 'invalid %s. State array has insufficient length.', s1 ) );
	}
	if ( state[ 0 ] !== STATE_ARRAY_VERSION ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible schema version. Expected: `%s`. Actual: `%s`.', s1, STATE_ARRAY_VERSION, state[ 0 ] ) );
	}
	if ( state[ 1 ] !== NUM_STATE_SECTIONS ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible number of sections. Expected: `%s`. Actual: `%s`.', s1, NUM_STATE_SECTIONS, state[ 1 ] ) );
	}
	if ( state[ STATE_SECTION_OFFSET ] !== N ) {
		return new RangeError( format( 'invalid %s. State array has an incompatible state length. Expected: `%u`. Actual: `%u`.', s1, N, state[ STATE_SECTION_OFFSET ] ) );
	}
	if ( state[ SEED_SECTION_OFFSET ] !== state.length-STATE_FIXED_LENGTH ) {
		return new RangeError( format( 'invalid %s. State array length is incompatible with seed section length. Expected: `%u`. Actual: `%u`.', s1, state.length-STATE_FIXED_LENGTH, state[ SEED_SECTION_OFFSET ] ) );
	}
	return null;
}

/**
* Returns an initial PRNG state.
*
* @private
* @param {Uint32Array} state - state array
* @param {PositiveInteger} N - state size (should be 4 for TinyMT32)
* @param {uinteger32} s - seed
* @returns {Uint32Array} state array
*/
function createState( state, N, s ) {
	var i;

	// Set the initial state values
	state[ 0 ] = s >>> 0;
	state[ 1 ] = MAT1;
	state[ 2 ] = MAT2;
	state[ 3 ] = TMAT;

	// Initialize using the algorithm from tinymt32_init
	for ( i = 1; i < MIN_LOOP; i++ ) {
		state[ i & 3 ] ^= i + unsignedMul(KNUTH_MULTIPLIER, (state[(i - 1) & 3] ^ (state[(i - 1) & 3] >>> 30)));
	}

	// Pre-run the algorithm to improve randomness of the initial state
	for ( i = 0; i < PRE_LOOP; i++ ) {
		nextState( state );
	}

	return state;
}

/**
* Function used in initialization by initState.
* @private
* @param {number} x - 32-bit integer
* @returns {number} 32-bit integer
*/
function iniFunc1(x) {
	return unsignedMul((x ^ (x >>> 27)), 1664525);
}

/**
* Function used in initialization by initState.
* @private
* @param {number} x - 32-bit integer
* @returns {number} 32-bit integer
*/
function iniFunc2(x) {
	return unsignedMul((x ^ (x >>> 27)), 1566083941);
}

/**
* Initializes the internal state array with an array of 32-bit unsigned integers used as seeds.
*
* @private
* @param {Uint32Array} state - state array
* @param {Uint32Array} initKey - array of 32-bit integers used as seeds
* @param {number} keyLength - length of initKey array
* @returns {void}
*/
function initState( state, initKey, keyLength ) {
	var count;
	var size = 4;
	var lag = 1;
	var mid = 1;
	var i;
	var j;
	var r;

	state[0] = 0;
	state[1] = MAT1;
	state[2] = MAT2;
	state[3] = TMAT;

	count = (keyLength + 1 > MIN_LOOP) ? keyLength + 1 : MIN_LOOP;

	r = iniFunc1(state[0] ^ state[mid % size] ^ state[(size - 1) % size]) >>> 0;
	state[mid % size] = (state[mid % size] + r) >>> 0;
	r = (r + keyLength) >>> 0;
	state[(mid + lag) % size] = (state[(mid + lag) % size] + r) >>> 0;
	state[0] = r;
	count -= 1;

	for (i = 1, j = 0; (j < count) && (j < keyLength); j++) {
		r = iniFunc1(state[i % size] ^ state[(i + mid) % size] ^ state[(i + size - 1) % size]) >>> 0;
		state[(i + mid) % size] = (state[(i + mid) % size] + r) >>> 0;
		r = (r + initKey[j] + i) >>> 0;
		state[(i + mid + lag) % size] = (state[(i + mid + lag) % size] + r) >>> 0;
		state[i % size] = r;
		i = (i + 1) % size;
	}

	for (; j < count; j++) {
		r = iniFunc1(state[i % size] ^ state[(i + mid) % size] ^ state[(i + size - 1) % size]) >>> 0;
		state[(i + mid) % size] = (state[(i + mid) % size] + r) >>> 0;
		r = (r + i) >>> 0;
		state[(i + mid + lag) % size] = (state[(i + mid + lag) % size] + r) >>> 0;
		state[i % size] = r;
		i = (i + 1) % size;
	}

	for (j = 0; j < size; j++) {
		r = iniFunc2(state[i % size] + state[(i + mid) % size] + state[(i + size - 1) % size]) >>> 0;
		state[(i + mid) % size] ^= r;
		r = (r - i) >>> 0;
		state[(i + mid + lag) % size] ^= r;
		state[i % size] = r;
		i = (i + 1) % size;
	}

	for (i = 0; i < PRE_LOOP; i++) {
		nextState(state);
	}
}

/**
* Updates TinyMT32's internal state.
*
* @private
* @param {Uint32Array} state - state array (length 4)
* @returns {Uint32Array} state array
*/
function nextState( state ) {
	var x;
	var y;

	// Mix state
	y = state[3];
	x = (state[0] & MASK) ^ state[1] ^ state[2];
	x ^= (x << SH0);
	y ^= (y >>> SH0) ^ x;
	state[0] = state[1];
	state[1] = state[2];
	state[2] = x ^ (y << SH1);
	state[3] = y;

	// Apply the tempering
	if (y & 1) {
		state[1] ^= MAT1;
		state[2] ^= MAT2;
	}

	return state;
}

/**
* Generates a tempered output from the state.
*
* @private
* @param {Uint32Array} state - state array
* @returns {number} tempered output
*/
function temper( state ) {
	var t0;
	var t1;

	// Tempering
	t0 = state[3];
	t1 = (state[0] + (state[2] >>> SH8)) >>> 0;
	t0 ^= t1;

	if ((t1 & 1) !== 0) {
		t0 ^= TMAT;
	}

	return t0 >>> 0; // Ensure unsigned 32-bit integer
}

/**
* Returns a pseudorandom integer on the interval \\( [0, 2^{32}) \\).
*
* @private
* @param {Uint32Array} state - generator state
* @returns {number} pseudorandom value
*/
function next( state ) {
	nextState( state );
	return temper( state );
}


// MAIN //

/**
* Returns a TinyMT32 pseudorandom number generator.
*
* ## Notes
*
* -   TinyMT32 uses a state of only 127 bits (vs MT19937's 19968 bits), making it more memory efficient.
* -   The period of TinyMT32 is 2^127-1, which is significantly shorter than MT19937, but still very large.
*
* @param {Options} [options] - options
* @param {PRNGSeedTinyMT32} [options.seed] - pseudorandom number generator seed
* @param {PRNGStateTinyMT32} [options.state] - pseudorandom number generator state
* @param {boolean} [options.copy=true] - boolean indicating whether to copy a provided pseudorandom number generator state
* @throws {TypeError} options argument must be an object
* @throws {TypeError} a seed must be either a positive integer less than the maximum unsigned 32-bit integer or an array-like object containing integers less than the maximum unsigned 32-bit integer
* @throws {RangeError} a numeric seed must be a positive integer less than the maximum unsigned 32-bit integer
* @throws {TypeError} state must be a Uint32Array
* @throws {Error} must provide a valid state
* @throws {TypeError} `copy` option must be a boolean
* @returns {PRNG} TinyMT32 PRNG
*
* @example
* var tinymt32 = factory();
*
* var v = tinymt32();
* // returns <number>
*
* @example
* // Return a seeded TinyMT32 PRNG:
* var tinymt32 = factory({
*     'seed': 1234
* });
*
* var v = tinymt32();
* // returns <number>
*/
function factory( options ) {
	var STATE;
	var state;
	var opts;
	var seed;
	var slen;
	var err;

	opts = {};
	if ( arguments.length ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		if ( hasOwnProp( options, 'copy' ) ) {
			opts.copy = options.copy;
			if ( !isBoolean( options.copy ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a boolean. Option: `%s`.', 'copy', options.copy ) );
			}
		}
		if ( hasOwnProp( options, 'state' ) ) {
			state = options.state;
			opts.state = true;
			if ( !isUint32Array( state ) ) {
				throw new TypeError( format( 'invalid option. `%s` option must be a Uint32Array. Option: `%s`.', 'state', state ) );
			}
			err = verifyState( state, true );
			if ( err ) {
				throw err;
			}
			if ( opts.copy === false ) {
				STATE = state;
			} else {
				STATE = new Uint32Array( state.length );
				gcopy( state.length, state, 1, STATE, 1 );
			}
			// Create a state "view":
			state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

			// Create a seed "view":
			seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), STATE[ SEED_SECTION_OFFSET ] );
		}
		// If provided a PRNG state, we ignore the `seed` option...
		if ( seed === void 0 ) {
			if ( hasOwnProp( options, 'seed' ) ) {
				seed = options.seed;
				opts.seed = true;
				if ( isPositiveInteger( seed ) ) {
					if ( seed > UINT32_MAX ) {
						throw new RangeError( format( 'invalid option. `%s` option must be a positive integer less than the maximum unsigned 32-bit integer. Option: `%u`.', 'seed', seed ) );
					}
					STATE = new Uint32Array( STATE_FIXED_LENGTH+1 );

					// Initialize sections:
					STATE[ 0 ] = STATE_ARRAY_VERSION;
					STATE[ 1 ] = NUM_STATE_SECTIONS;
					STATE[ STATE_SECTION_OFFSET ] = N;
					STATE[ SEED_SECTION_OFFSET ] = 1;
					STATE[ SEED_SECTION_OFFSET+1 ] = seed >>> 0;

					// Create a state "view":
					state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

					// Create a seed "view":
					seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), 1 );

					// Initialize the internal PRNG state:
					createState(state, N, seed[0]);
				} else if ( isCollection( seed ) && seed.length > 0 ) {
					slen = seed.length;
					STATE = new Uint32Array( STATE_FIXED_LENGTH+slen );

					// Initialize sections:
					STATE[ 0 ] = STATE_ARRAY_VERSION;
					STATE[ 1 ] = NUM_STATE_SECTIONS;
					STATE[ STATE_SECTION_OFFSET ] = N;
					STATE[ SEED_SECTION_OFFSET ] = slen;

					// Copy the provided seed array to prevent external mutation:
					gcopy.ndarray( slen, seed, 1, 0, STATE, 1, SEED_SECTION_OFFSET+1 );

					// Create a state "view":
					state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

					// Create a seed "view":
					seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), slen );

					// Initialize the internal PRNG state using seed array:
					initState(state, seed, slen);
				} else {
					throw new TypeError( format( 'invalid option. `%s` option must be either a positive integer less than the maximum unsigned 32-bit integer or an array-like object containing integer values less than the maximum unsigned 32-bit integer. Option: `%s`.', 'seed', seed ) );
				}
			} else {
				seed = randuint32() >>> 0; // asm type annotation
			}
		}
	} else {
		seed = randuint32() >>> 0; // asm type annotation
	}
	if ( state === void 0 ) {
		STATE = new Uint32Array( STATE_FIXED_LENGTH + 1 );

		// Initialize sections:
		STATE[ 0 ] = STATE_ARRAY_VERSION;
		STATE[ 1 ] = NUM_STATE_SECTIONS;
		STATE[ STATE_SECTION_OFFSET ] = N;
		STATE[ SEED_SECTION_OFFSET ] = 1;
		STATE[ SEED_SECTION_OFFSET+1 ] = seed;

		// Create a state "view":
		state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

		// Create a seed "view":
		seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), 1 );

		// Initialize the internal PRNG state:
		createState(state, N, seed[0]);
	}

	// Note: property order matters in order to maintain consistency of PRNG "shape" (hidden classes).
	setReadOnly( tinymt32, 'NAME', 'tinymt32' );
	setReadOnlyAccessor( tinymt32, 'seed', getSeed );
	setReadOnlyAccessor( tinymt32, 'seedLength', getSeedLength );
	setReadWriteAccessor( tinymt32, 'state', getState, setState );
	setReadOnlyAccessor( tinymt32, 'stateLength', getStateLength );
	setReadOnlyAccessor( tinymt32, 'byteLength', getStateSize );
	setReadOnly( tinymt32, 'toJSON', toJSON );
	setReadOnly( tinymt32, 'MIN', 0 );
	setReadOnly( tinymt32, 'MAX', UINT32_MAX );
	setReadOnly( tinymt32, 'normalized', normalized );

	setReadOnly( normalized, 'NAME', tinymt32.NAME );
	setReadOnlyAccessor( normalized, 'seed', getSeed );
	setReadOnlyAccessor( normalized, 'seedLength', getSeedLength );
	setReadWriteAccessor( normalized, 'state', getState, setState );
	setReadOnlyAccessor( normalized, 'stateLength', getStateLength );
	setReadOnlyAccessor( normalized, 'byteLength', getStateSize );
	setReadOnly( normalized, 'toJSON', toJSON );
	setReadOnly( normalized, 'MIN', 0.0 );
	setReadOnly( normalized, 'MAX', MAX_NORMALIZED );

	return tinymt32;

	/**
	* Returns the PRNG seed.
	*
	* @private
	* @returns {PRNGSeedTinyMT32} seed
	*/
	function getSeed() {
		return seed;
	}

	/**
	* Returns the PRNG seed length.
	*
	* @private
	* @returns {PositiveInteger} seed length
	*/
	function getSeedLength() {
		return seed.length;
	}

	/**
	* Returns the PRNG state length.
	*
	* @private
	* @returns {PositiveInteger} state length
	*/
	function getStateLength() {
		return state.length;
	}

	/**
	* Returns the PRNG state size (in bytes).
	*
	* @private
	* @returns {PositiveInteger} state size (in bytes)
	*/
	function getStateSize() {
		return STATE.byteLength;
	}

	/**
	* Returns the current pseudorandom number generator state.
	*
	* @private
	* @returns {PRNGStateTinyMT32} current state
	*/
	function getState() {
		var out = new Uint32Array( STATE.length );
		gcopy( STATE.length, STATE, 1, out, 1 );
		return out;
	}

	/**
	* Sets the PRNG state.
	*
	* ## Notes
	*
	* -   If PRNG state is "shared" (meaning a state array was provided during PRNG creation and **not** copied) and one sets the generator state to a state array having a different length, the PRNG does **not** update the existing shared state and, instead, points to the newly provided state array. In order to synchronize PRNG output according to the new shared state array, the state array for **each** relevant PRNG must be **explicitly** set.
	* -   If PRNG state is "shared" and one sets the generator state to a state array of the same length, the PRNG state is updated (along with the state of all other PRNGs sharing the PRNG's state array).
	*
	* @private
	* @param {PRNGStateTinyMT32} s - generator state
	* @throws {TypeError} must provide a `Uint32Array`
	* @throws {Error} must provide a valid state
	*/
	function setState( s ) {
		var err;

		if ( !isUint32Array( s ) ) {
			throw new TypeError( format( 'invalid argument. Must provide a Uint32Array. Value: `%s`.', s ) );
		}
		err = verifyState( s, false );
		if ( err ) {
			throw err;
		}
		if ( opts.copy === false ) {
			if ( opts.state && s.length === STATE.length ) {
				gcopy( s.length, s, 1, STATE, 1 ); // update current shared state
			} else {
				STATE = s; // point to new shared state
				opts.state = true; // setting this flag allows updating a shared state even if a state array was not provided at PRNG creation
			}
		} else {
			// Check if we can reuse allocated memory...
			if ( s.length !== STATE.length ) {
				STATE = new Uint32Array( s.length ); // reallocate
			}
			gcopy( s.length, s, 1, STATE, 1 );
		}
		// Create a new state "view":
		state = new Uint32Array( STATE.buffer, STATE.byteOffset+((STATE_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), N );

		// Create a new seed "view":
		seed = new Uint32Array( STATE.buffer, STATE.byteOffset+((SEED_SECTION_OFFSET+1)*STATE.BYTES_PER_ELEMENT), STATE[ SEED_SECTION_OFFSET ] );
	}

	/**
	* Serializes the pseudorandom number generator as a JSON object.
	*
	* ## Notes
	*
	* -   `JSON.stringify()` implicitly calls this method when stringifying a PRNG.
	*
	* @private
	* @returns {Object} JSON representation
	*/
	function toJSON() {
		var out = {};
		out.type = 'PRNG';
		out.name = tinymt32.NAME;
		out.state = typedarray2json( STATE );
		out.params = [];
		return out;
	}

	/**
	* Generates a pseudorandom number on the interval \\( [0, 1) \\).
	*
	* ## Notes
	*
	* -   The original C implementation credits Isaku Wada for this algorithm (2002/01/09).
	*
	* @private
	* @returns {number} pseudorandom number
	*
	* @example
	* var r = normalized();
	* // returns <number>
	*/
	function normalized() {
		var x = tinymt32() >>> 5;
		var y = tinymt32() >>> 6;
		return ( (x*TWO_26)+y ) * FLOAT64_NORMALIZATION_CONSTANT;
	}

	/**
	* Returns a pseudorandom integer on the interval \\([0,2^{32})\\).
	*
	* @private
	* @returns {number} pseudorandom number
	*/
	function tinymt32() {
		return next(state);
	}
}

module.exports = factory;
